//! Consumer dispatch: Node.js → IPC.
//!
//! Lets JavaScript call methods of remote IPC services through the generic
//! `callService(service, method, args)` and `callServiceStream(...)` APIs.
//!
//! # Where the `(service, method)` surface comes from
//!
//! The methods are **generated by `#[service]`**: this module declares no method
//! table of its own, it invokes the single JSON view the macro emits for each
//! service. The *services* are the ones the addon's table names
//! ([`crate::services::GatewayService`]), so the consumer side and the provider
//! side cannot disagree: both read the same list.
//!
//! # Call flow
//!
//! 1. JS: `await gateway.callService('DatabaseService', 'get_user_age', 'Alice')`
//! 2. N-API → [`call_ipc_method`] → the generated
//!    `JsonInvoker::invoke_json_stream`
//! 3. Proxy retrieval through [`ice_rpc::ServiceLocator::get`]
//! 4. Business call (IPC to the remote provider)
//! 5. `callService` takes the first event (`first_json`, which cancels the
//!    rest); `callServiceStream` drains a **finite** stream into an array.
//!
//! Both entry points consume the single stream view. `callServiceStream` is a
//! collecting call, not a push API: a stream that never completes never
//! resolves.

use crate::error::{GatewayError, GatewayErrorCode};
use crate::services::{GatewayService, unknown_service_error};
use ice_rpc::codegen::{
    JsonCallError, JsonEventSink, JsonInvoker, JsonOutcome, JsonStreamEvent, first_json,
};
use serde_json::Value;
use std::sync::Arc;

/// Events buffered between the service and the collecting loop.
///
/// Bounds how far the service may run ahead while [`call_ipc_method_stream`]
/// drains its events; it does not bound the result, which is the array itself.
const STREAM_EVENTS_BUFFER: usize = 16;

/// Calls a method of a remote IPC service and returns its first value as JSON.
///
/// Answers as soon as the first value is available, which is the only mode able
/// to serve a service that streams without ever completing.
///
/// # Errors
/// `E_UNKNOWN_SERVICE`, `E_UNKNOWN_METHOD`, `E_INVALID_ARGS`, `E_NO_PROVIDER`,
/// `E_TRANSPORT`, `E_ONE_WAY` when the method is a notification, or
/// `E_BUSINESS` when the service failed **or completed without emitting any
/// value** — a bare `null` could not be told apart from a real `null` payload.
/// See [`GatewayErrorCode`].
pub async fn call_ipc_method(
    table: &'static [GatewayService],
    service: &str,
    method: &str,
    args: Value,
) -> Result<Value, GatewayError> {
    match first_outcome(table, service, method, args).await? {
        JsonOutcome::Value(value) => Ok(value),
        JsonOutcome::Nothing => Err(no_value(service, method)),
        // No value can ever exist: naming the contract beats a `null` payload.
        JsonOutcome::Accepted { .. } => Err(one_way(service, method)),
    }
}

/// Calls a method of a remote IPC service and returns **every** value it emits.
///
/// The multi-value counterpart of [`call_ipc_method`], for a **finite** stream:
/// it drains `JsonInvoker::invoke_json_stream` and waits for the terminal event.
/// An empty stream is a legitimate empty result here, whereas
/// [`call_ipc_method`] has to report a missing value.
///
/// This is a **collecting** call, not a push API: a stream that never completes
/// never resolves, and the array grows with every value.
pub async fn call_ipc_method_stream(
    table: &'static [GatewayService],
    service: &str,
    method: &str,
    args: Value,
) -> Result<Vec<Value>, GatewayError> {
    let invoker = resolve_invoker(table, service).await?;
    let (sink, receiver) = JsonEventSink::bounded(STREAM_EVENTS_BUFFER);

    /// How one drained stream ended.
    enum Drained {
        /// The service completed; carries every value it emitted.
        Completed(Vec<Value>),
        /// The method is one-way: nothing will ever be answered.
        Accepted,
        /// The service or the transport failed.
        Failed(JsonCallError),
    }

    let drain = async move {
        let mut values = Vec::new();
        while let Ok(event) = receiver.recv().await {
            match event {
                JsonStreamEvent::Next(value) => values.push(value),
                JsonStreamEvent::Complete => return Drained::Completed(values),
                JsonStreamEvent::Accepted { .. } => return Drained::Accepted,
                JsonStreamEvent::Failed(error) => return Drained::Failed(error),
                // A kind this build does not know: refuse it instead of
                // silently truncating the answer.
                _ => {
                    return Drained::Failed(JsonCallError::Transport(
                        "unsupported stream event".to_string(),
                    ));
                }
            }
        }
        // The generated view always reports a terminal event; a producer that
        // vanished without one is a transport failure, not a clean empty result.
        Drained::Failed(JsonCallError::Transport(
            "stream closed before completion".to_string(),
        ))
    };

    // The call writes into the sink while `drain` reads it. Polling both at once
    // is what keeps the bounded sink from filling and stalling the service.
    let (called, drained) = ice_rpc::codegen::futures_lite::future::zip(
        invoker.invoke_json_stream(method, args, sink),
        drain,
    )
    .await;

    // `None` is "no such method": the sink was dropped without an event.
    if called.is_none() {
        return Err(unknown_method(service, method));
    }

    match drained {
        Drained::Completed(values) => Ok(values),
        Drained::Accepted => Err(one_way(service, method)),
        Drained::Failed(error) => Err(call_error(error)),
    }
}

/// Resolves the service, reads its invoker and takes the first event.
async fn first_outcome(
    table: &'static [GatewayService],
    service: &str,
    method: &str,
    args: Value,
) -> Result<JsonOutcome, GatewayError> {
    let invoker = resolve_invoker(table, service).await?;
    // `None` means "no such method"; `Some` is returned even when the call fails.
    match first_json(invoker.as_ref(), method, args).await {
        Some(result) => result.map_err(call_error),
        None => Err(unknown_method(service, method)),
    }
}

/// Resolves the consumer proxy of `service`, or the error explaining why it is
/// not reachable.
async fn resolve_invoker(
    table: &'static [GatewayService],
    service: &str,
) -> Result<Arc<dyn JsonInvoker>, GatewayError> {
    let entry = table
        .iter()
        .find(|entry| entry.name == service)
        .ok_or_else(|| unknown_service_error(table, service))?;
    (entry.invoker)().await.ok_or_else(|| no_provider(service))
}

/// Maps the failure reported by the generated JSON view onto the gateway codes.
///
/// Keeping the mapping here is what lets the generated code stay free of any
/// gateway type: [`JsonInvoker`] reports a [`JsonCallError`], the gateway owns
/// the stable codes.
fn call_error(error: JsonCallError) -> GatewayError {
    let (code, message) = match error {
        JsonCallError::InvalidArgs(message) => (GatewayErrorCode::InvalidArgs, message),
        JsonCallError::Business(message) => (GatewayErrorCode::Business, message),
        JsonCallError::Transport(message) => (GatewayErrorCode::Transport, message),
    };
    GatewayError::new(code, message)
}

/// Builds the `E_BUSINESS` failure of a single-value call that emitted nothing.
///
/// The call itself succeeded — the service simply completed without a value. A
/// `null` answer would be indistinguishable from a real `null` payload, which is
/// why the absence is reported as a failure on the single-value entry point.
fn no_value(service: &str, method: &str) -> GatewayError {
    GatewayError::new(
        GatewayErrorCode::Business,
        format!("'{service}.{method}' completed without emitting a value"),
    )
}

/// Builds the `E_ONE_WAY` failure of a call that asked for a result.
///
/// A one-way method is a notification: the sample was published, and no answer
/// will ever exist. Returning `null` (or an empty array) would make it look like
/// an answered call that carried nothing — the very confusion
/// [`JsonOutcome::Nothing`] exists to avoid.
fn one_way(service: &str, method: &str) -> GatewayError {
    GatewayError::new(
        GatewayErrorCode::OneWay,
        format!("'{service}.{method}' is a one-way method and has no result"),
    )
}

/// Builds the `E_NO_PROVIDER` failure for a service nobody advertises.
fn no_provider(service: &str) -> GatewayError {
    GatewayError::new(
        GatewayErrorCode::NoProvider,
        format!("no provider is connected for '{service}'"),
    )
}

/// Builds the `E_UNKNOWN_METHOD` failure of a known service.
fn unknown_method(service: &str, method: &str) -> GatewayError {
    GatewayError::new(
        GatewayErrorCode::UnknownMethod,
        format!("'{service}' has no method '{method}'"),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// An invoker that answers `None` for every method (no such method) — the
    /// shape that must map to `E_UNKNOWN_METHOD`, not to a failure.
    struct NoMethod;

    #[async_trait::async_trait]
    impl JsonInvoker for NoMethod {
        fn service_name(&self) -> &'static str {
            "MockService"
        }

        async fn invoke_json_stream(
            &self,
            _method: &str,
            _args: Value,
            _sink: JsonEventSink,
        ) -> Option<()> {
            None
        }
    }

    /// An invoker whose stream view answers a finite set of events.
    struct StreamingInvoker;

    #[async_trait::async_trait]
    impl JsonInvoker for StreamingInvoker {
        fn service_name(&self) -> &'static str {
            "StreamService"
        }

        async fn invoke_json_stream(
            &self,
            method: &str,
            _args: Value,
            sink: JsonEventSink,
        ) -> Option<()> {
            match method {
                "values" => {
                    for value in [1, 2, 3] {
                        if !sink
                            .send(JsonStreamEvent::Next(serde_json::json!(value)))
                            .await
                        {
                            return Some(());
                        }
                    }
                    let _ = sink.send(JsonStreamEvent::Complete).await;
                    Some(())
                }
                "oneway" => {
                    let _ = sink
                        .send(JsonStreamEvent::Accepted { delivered: true })
                        .await;
                    Some(())
                }
                "fail" => {
                    let _ = sink
                        .fail(JsonCallError::Business("denied".to_string()))
                        .await;
                    Some(())
                }
                _ => None,
            }
        }
    }

    fn provide() -> crate::services::BoxFuture<'static, ()> {
        Box::pin(async {})
    }

    fn known_invoker() -> crate::services::BoxFuture<'static, Option<Arc<dyn JsonInvoker>>> {
        Box::pin(async { Some(Arc::new(NoMethod) as Arc<dyn JsonInvoker>) })
    }

    fn absent_invoker() -> crate::services::BoxFuture<'static, Option<Arc<dyn JsonInvoker>>> {
        Box::pin(async { None })
    }

    fn streaming_invoker() -> crate::services::BoxFuture<'static, Option<Arc<dyn JsonInvoker>>> {
        Box::pin(async { Some(Arc::new(StreamingInvoker) as Arc<dyn JsonInvoker>) })
    }

    static TABLE: &[GatewayService] = &[
        GatewayService {
            name: "MockService",
            provide,
            invoker: known_invoker,
        },
        GatewayService {
            name: "OfflineService",
            provide,
            invoker: absent_invoker,
        },
        GatewayService {
            name: "StreamService",
            provide,
            invoker: streaming_invoker,
        },
    ];

    #[test]
    fn an_unknown_service_lists_the_served_ones() {
        let error = unknown_service_error(TABLE, "NoSuchService");
        assert_eq!(error.code(), GatewayErrorCode::UnknownService);
        for name in crate::services::known_service_names(TABLE) {
            assert!(error.message().contains(name), "{}", error.message());
        }
    }

    #[test]
    fn an_unknown_method_names_the_service_and_the_method() {
        let error = unknown_method("MockService", "nope");
        assert_eq!(error.code(), GatewayErrorCode::UnknownMethod);
        assert!(error.message().contains("MockService"));
        assert!(error.message().contains("nope"));
    }

    #[test]
    fn a_missing_provider_is_reported_on_its_own_code() {
        let error = no_provider("OfflineService");
        assert_eq!(error.code(), GatewayErrorCode::NoProvider);
        assert!(error.message().contains("OfflineService"));
    }

    #[test]
    fn every_generated_failure_kind_maps_to_a_code() {
        let cases = [
            (
                JsonCallError::InvalidArgs("boom".to_string()),
                GatewayErrorCode::InvalidArgs,
            ),
            (
                JsonCallError::Business("boom".to_string()),
                GatewayErrorCode::Business,
            ),
            (
                JsonCallError::Transport("boom".to_string()),
                GatewayErrorCode::Transport,
            ),
        ];
        for (error, expected) in cases {
            let mapped = call_error(error);
            assert_eq!(mapped.code(), expected);
            assert_eq!(mapped.message(), "boom");
        }
    }

    #[test]
    fn a_completion_without_a_value_is_a_business_failure() {
        let error = no_value("MockService", "watch");
        assert_eq!(error.code(), GatewayErrorCode::Business);
        assert!(error.message().contains("MockService.watch"));
    }

    #[test]
    fn a_finite_stream_is_collected_in_order() {
        let values = ice_rpc::rt::block_on(call_ipc_method_stream(
            TABLE,
            "StreamService",
            "values",
            Value::Null,
        ))
        .expect("a finite stream completes");

        assert_eq!(
            values,
            vec![
                serde_json::json!(1),
                serde_json::json!(2),
                serde_json::json!(3)
            ]
        );
    }

    #[test]
    fn a_one_way_stream_is_refused() {
        let error = ice_rpc::rt::block_on(call_ipc_method_stream(
            TABLE,
            "StreamService",
            "oneway",
            Value::Null,
        ))
        .expect_err("a one-way method has no result");

        assert_eq!(error.code(), GatewayErrorCode::OneWay);
    }

    #[test]
    fn a_stream_failure_keeps_its_code() {
        let error = ice_rpc::rt::block_on(call_ipc_method_stream(
            TABLE,
            "StreamService",
            "fail",
            Value::Null,
        ))
        .expect_err("the service failed");

        assert_eq!(error.code(), GatewayErrorCode::Business);
        assert_eq!(error.message(), "denied");
    }

    #[test]
    fn an_unknown_stream_method_is_reported() {
        let error = ice_rpc::rt::block_on(call_ipc_method_stream(
            TABLE,
            "StreamService",
            "nope",
            Value::Null,
        ))
        .expect_err("no such method");

        assert_eq!(error.code(), GatewayErrorCode::UnknownMethod);
    }
}
